    fn allocate (&self, layout: Layout ) -> Result < NonNull <[ u8 ]>, AllocError >; unsafe fn deallocate (&self, ptr: NonNull < u8 >, layout: Layout );

    // Provided methods
    fn allocate_zeroed (
        &self,
        layout: Layout ,
    ) -> Result < NonNull <[ u8 ]>, AllocError > { ... } unsafe fn grow (
        &self,
        ptr: NonNull < u8 >,
        old_layout: Layout ,
        new_layout: Layout ,
    ) -> Result < NonNull <[ u8 ]>, AllocError > { ... } unsafe fn grow_zeroed (
        &self,
        ptr: NonNull < u8 >,
        old_layout: Layout ,
        new_layout: Layout ,
    ) -> Result < NonNull <[ u8 ]>, AllocError > { ... } unsafe fn shrink (
        &self,
        ptr: NonNull < u8 >,
        old_layout: Layout ,
        new_layout: Layout ,
    ) -> Result < NonNull <[ u8 ]>, AllocError > { ... } fn by_ref (&self) -> &Self where Self: Sized { ... }
}

